using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class TreeAudit162{public static string Main(){var log=new System.Text.StringBuilder();foreach(var n in new[]{"TreeHouse_1","TreeHouse_2"}){var r=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Locations/Enemy/"+n+".prefab");log.AppendLine(n);foreach(var t in r.GetComponentsInChildren<Transform>().Where(t=>t.parent==r.transform||t.name.IndexOf("tree",StringComparison.OrdinalIgnoreCase)>=0||t.name.IndexOf("stair",StringComparison.OrdinalIgnoreCase)>=0||t.name.IndexOf("house",StringComparison.OrdinalIgnoreCase)>=0)){var rs=t.GetComponentsInChildren<Renderer>();if(rs.Length==0)continue;var b=rs[0].bounds;foreach(var rr in rs)b.Encapsulate(rr.bounds);log.AppendLine(t.name+" pos="+t.position+" bounds="+b+" source="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject));}var sp=r.GetComponent<LocationContentSpawner>();log.AppendLine("items="+string.Join(";",sp.itemSpawnPoints.Select(p=>p.spawnTransform.position.ToString()))+" enemies="+sp.enemySpawnPoints.Count);}return log.ToString();}}
